docs1 = retrieve("Are there any specific rebate programs for commercial customers installing electric vehicle charging stations in Environmental Justice Areas in PECO's service territory?")
rebate_programs = answer("Are there any specific rebate programs for commercial customers installing electric vehicle charging stations in Environmental Justice Areas in PECO's service territory?", docs1)

if rebate_programs:
    docs2 = retrieve("If yes, what is the rebate amount per charging port for such programs?")
    rebate_amount = answer("If yes, what is the rebate amount per charging port for such programs?", docs2)
else:
    rebate_amount = "No specific rebate programs are available."

final_answer = answer(
    f"Given: {rebate_programs}, {rebate_amount}. Answer the question: If I am a commercial customer in the PECO electric service territory and want to install an electric vehicle charging station in an Environmental Justice Area, what is the rebate amount per charging port?"
)
